+
+/* Compact saved-device cards: UX polish 2026-09-11 */
+.sensor-saved-card {
+  gap: var(--lcl-spacing-sm);
+  padding: var(--lcl-spacing-md);
+}
+
+.sensor-card-header {
+  align-items: center;
+  display: grid;
+  gap: var(--lcl-spacing-sm);
+  grid-template-columns: minmax(0, 1fr) auto;
+}
+
+.sensor-card-title-row,
+.sensor-card-actions {
+  align-items: center;
+  display: flex;
+  gap: var(--lcl-spacing-xs);
+  min-width: 0;
+}
+
+.sensor-card-title-row h3 {
+  min-width: 0;
+  overflow-wrap: anywhere;
+}
+
+.sensor-card-name-input {
+  min-height: var(--lcl-size-compact-control-min-height);
+  min-width: 0;
+  width: 100%;
+}
+
