+  font-weight: var(--lcl-font-weight-bold);
+  margin: 0;
+  min-width: 0;
+  overflow-wrap: anywhere;
+  text-align: right;
+}
+
+.sensor-card-details__wide {
+  grid-column: 1 / -1;
+}
